const input = $json;
const findings = input.clean_findings || [];

// 1. Exploitability Scoring Matrix:
// RCE / Backdoors (100) > Exposed RDP / Unauthenticated (85) > Outdated with CVE (70) > Weak Ciphers (50) > Low / Banner (20)
function scoreExploitability(item) {
  const text = `${item.finding} ${item.details} ${item.version}`.toLowerCase();
  if (text.includes('backdoor') || text.includes('vsftpd 2.3.4')) return 100;
  if (text.includes('arbitrary file') || text.includes('tomcat 8.0')) return 90;
  if (text.includes('rdp') && text.includes('nla disabled')) return 85;
  if (text.includes('telnet') || text.includes('cleartext')) return 80;
  if (text.includes('openssh 7.2')) return 70;
  if (text.includes('tls 1.0') || text.includes('3des')) return 50;
  if (item.severity === 'low') return 15;
  return 40;
}

// 2. One-line remediation fixes
function getOneLineFix(item) {
  const text = `${item.finding} ${item.version}`.toLowerCase();
  if (text.includes('vsftpd 2.3.4')) return 'Upgrade vsftpd to version 3.0.5+ immediately or replace with hardened SFTP.';
  if (text.includes('tomcat 8.0')) return 'Upgrade Apache Tomcat to supported 10.1.x/9.0.x and disable PUT method uploads.';
  if (text.includes('rdp')) return 'Enable Network Level Authentication (NLA) and restrict port 3389 behind a secure VPN gateway.';
  if (text.includes('telnet')) return 'Disable the telnet daemon service and transition all remote management to SSH key authentication.';
  if (text.includes('openssh')) return 'Update OpenSSH to >= 9.8 and disable deprecated CBC ciphers in sshd_config.';
  if (text.includes('tls') || text.includes('3des')) return 'Disable TLS 1.0/1.1 and 3DES cipher suites; enforce TLS 1.2/1.3 with AES-GCM suites.';
  return 'Apply latest vendor security patch and restrict port access to trusted management subnets.';
}

const scored = findings.map(f => ({
  ...f,
  score: scoreExploitability(f),
  fix: getOneLineFix(f)
}));

// Sort highest exploitability first
scored.sort((a, b) => b.score - a.score);

// Pick Top 2
const top1 = scored[0];
const top2 = scored[1] || scored[0];

// Low-severity summary in a single line
const lowSeverity = scored.filter(f => f.severity === 'low');
const lowSummary = `${lowSeverity.length} low-severity finding(s) detected (${lowSeverity.map(l => l.service).join(', ')}): review banners and recursive queries during standard maintenance.`;

// 3. Current IST Time (UTC + 5:30)
const now = new Date();
const istOffset = 5.5 * 60 * 60 * 1000;
const istDate = new Date(now.getTime() + istOffset);
const istTime = istDate.toISOString().replace('T', ' ').substring(0, 19) + ' IST';

const execId = $execution.id || Math.floor(1000 + Math.random() * 9000);
const verdict = 'CRITICAL / EXPLOITABLE';
const oneLineSummary = `Immediate RCE risk on ${top1.asset_ip}:${top1.port} (${top1.service}) and code execution on ${top2.asset_ip}`;

// Rubric Header Format:
// 🟣 NGP-028 | exec #<execution id> | <IST time> | <verdict / severity> | <one-line summary>
const header = `🟣 NGP-028 | exec #${execId} | ${istTime} | ${verdict} | ${oneLineSummary}`;

const message = `${header}\n\n` +
  `🏆 *Top-2 Exploitable Findings (Ranked):*\n\n` +
  `*1. [Rank 1 - ${top1.severity.toUpperCase()}] ${top1.finding}*\n` +
  `   • *Asset:* \`${top1.asset_ip}:${top1.port}\` (${top1.service} ${top1.version})\n` +
  `   • *Risk:* ${top1.details}\n` +
  `   • *One-Line Fix:* \`${top1.fix}\`\n\n` +
  `*2. [Rank 2 - ${top2.severity.toUpperCase()}] ${top2.finding}*\n` +
  `   • *Asset:* \`${top2.asset_ip}:${top2.port}\` (${top2.service} ${top2.version})\n` +
  `   • *Risk:* ${top2.details}\n` +
  `   • *One-Line Fix:* \`${top2.fix}\`\n\n` +
  `ℹ️ *Low-Severity Summary:*\n${lowSummary}\n\n` +
  `🛡️ *S5 Data Minimisation Proof:*\n` +
  `• Raw Ingested: *${input.before_count}* | Duplicates Removed: *${input.duplicates_removed}* | Sanitised: *${input.after_count}*\n` +
  `• *Raw IP and owner contact details were removed before ranking (last octet masked, owner name and email stripped).*\n` +
  `• *Masked example:* \`${input.after_sample.asset_ip}\``;

return [{
  json: {
    telegram_text: message
  }
}];

// Sample Scan Data (10 Findings with open ports, outdated versions, weak ciphers & duplicates)
const raw_findings = [
  { id: "SEC-001", asset_ip: "192.168.1.45", port: 21, service: "FTP", version: "vsftpd 2.3.4", severity: "critical", finding: "Backdoored vsftpd service running", details: "Known smiley backdoor CVE-2011-2523 allows unauthenticated RCE.", owner_name: "John Doe", owner_email: "johndoe@corp.local" },
  { id: "SEC-002", asset_ip: "192.168.1.72", port: 8080, service: "HTTP", version: "Apache Tomcat 8.0.32", severity: "high", finding: "Outdated Apache Tomcat server", details: "Arbitrary file upload & RCE vulnerability (CVE-2017-12615).", owner_name: "Alice Smith", owner_email: "asmith@corp.local" },
  { id: "SEC-003", asset_ip: "192.168.1.18", port: 22, service: "SSH", version: "OpenSSH 7.2p2", severity: "high", finding: "Outdated SSH service version", details: "Vulnerable to user enumeration and legacy CBC ciphers.", owner_name: "DevSecOps", owner_email: "secops@corp.local" },
  { id: "SEC-004", asset_ip: "192.168.1.99", port: 3389, service: "RDP", version: "Windows RDP (NLA Disabled)", severity: "high", finding: "Exposed RDP with NLA disabled", details: "Port open without NLA; prone to BlueKeep (CVE-2019-0708).", owner_name: "Admin IT", owner_email: "admin@corp.local" },
  { id: "SEC-005", asset_ip: "192.168.1.110", port: 443, service: "HTTPS", version: "TLS 1.0 Enabled", severity: "medium", finding: "Deprecated TLS protocol enabled", details: "Vulnerable to BEAST cryptographic downgrade attacks.", owner_name: "SecOps", owner_email: "secops@corp.local" },
  { id: "SEC-006", asset_ip: "192.168.1.110", port: 8443, service: "HTTPS-alt", version: "TLS_RSA_WITH_3DES_EDE_CBC_SHA", severity: "medium", finding: "Weak 3DES cipher suite supported", details: "Sweet32 collision attack on 64-bit block ciphers.", owner_name: "SecOps", owner_email: "secops@corp.local" },
  { id: "SEC-007", asset_ip: "192.168.1.15", port: 23, service: "Telnet", version: "Linux Telnetd", severity: "high", finding: "Cleartext Telnet service exposed", details: "Plaintext credentials transmitted unencrypted across network.", owner_name: "Net Admin", owner_email: "net@corp.local" },
  { id: "SEC-008", asset_ip: "192.168.1.200", port: 80, service: "HTTP", version: "nginx 1.14.0", severity: "low", finding: "Server version banner disclosure in HTTP header", details: "Exact nginx version disclosed in headers.", owner_name: "Web Admin", owner_email: "web@corp.local" },
  { id: "SEC-009", asset_ip: "192.168.1.201", port: 53, service: "DNS", version: "BIND 9.11", severity: "low", finding: "DNS recursion enabled for external queries", details: "Open resolver risk for DNS amplification.", owner_name: "Net Admin", owner_email: "net@corp.local" },
  { id: "SEC-010", asset_ip: "192.168.1.45", port: 21, service: "FTP", version: "vsftpd 2.3.4", severity: "critical", finding: "Backdoored vsftpd service running", details: "Duplicate entry of SEC-001 for deduplication testing.", owner_name: "John Doe", owner_email: "johndoe@corp.local" }
];

// --- 1. S5 Before: Record raw items ---
const before_count = raw_findings.length;
const before_sample = raw_findings[0]; // Shows raw IP and email

// --- 2. Deduplication ---
const seen = new Set();
const deduplicated = [];
for (const item of raw_findings) {
  const key = `${item.asset_ip}:${item.port}:${item.finding}`;
  if (!seen.has(key)) {
    seen.add(key);
    deduplicated.push(item);
  }
}

// --- 3. S5 Data Minimisation: Mask IP last octet & strip personal emails ---
const after_items = deduplicated.map(item => {
  const masked_ip = item.asset_ip.replace(/^(\d+\.\d+\.\d+)\.\d+$/, '$1.xxx');
  return {
    id: item.id,
    asset_ip: masked_ip,
    port: item.port,
    service: item.service,
    version: item.version,
    severity: item.severity,
    finding: item.finding,
    details: item.details
    // Note: owner_name and owner_email are deliberately stripped here!
  };
});

return [{
  json: {
    tag: "NGP-028",
    before_count: before_count,
    after_count: after_items.length,
    duplicates_removed: before_count - after_items.length,
    before_sample: before_sample,
    after_sample: after_items[0],
    clean_findings: after_items
  }
}];
